struct Player {
    name: String,
    health: i32,
    max_health: i32,
    attack: i32,
    defense: i32,
    level: i32,
    experience: i32,
}

impl Player {
    // ---- Associated function (constructor) ----
    // Called with :: (e.g., Player::new())
    fn new(name: &str) -> Player {
        Player {
            name: String::from(name),
            health: 100,
            max_health: 100,
            attack: 10,
            defense: 5,
            level: 1,
            experience: 0,
        }
    }

    // ---- Method (borrows self immutably) ----
    // Called with . (e.g., player.display())
    fn display(&self) {
        println!("=== {} ===", self.name);
        println!("Level: {}", self.level);
        println!("Health: {}/{}", self.health, self.max_health);
        println!("Attack: {}", self.attack);
        println!("Defense: {}", self.defense);
        println!("Experience: {}/{}", self.experience, self.level * 100);
    }

    // ---- Method (borrows self mutably) ----
    fn take_damage(&mut self, damage: i32) {
        let actual_damage = damage - self.defense / 2;
        if actual_damage > 0 {
            self.health -= actual_damage;
            if self.health < 0 {
                self.health = 0;
            }
            println!("{} took {} damage! Health: {}", self.name, actual_damage, self.health);
        } else {
            println!("{} blocked the attack!", self.name);
        }
    }

    fn heal(&mut self, amount: i32) {
        self.health += amount;
        if self.health > self.max_health {
            self.health = self.max_health;
        }
        println!("{} healed! Health: {}", self.name, self.health);
    }

    // ---- Method that takes ownership ----
    fn die(self) {
        println!("{} has been defeated!", self.name);
        // self is dropped here
    }

    // ---- Method that returns a value ----
    fn is_alive(&self) -> bool {
        self.health > 0
    }

    // ---- Method with multiple parameters ----
    fn attack_target(&mut self, target: &mut Player) {
        if !self.is_alive() {
            println!("{} cannot attack! They're dead.", self.name);
            return;
        }

        let damage = self.attack + (self.level * 2);
        println!("{} attacks {} for {} damage!", self.name, target.name, damage);
        target.take_damage(damage);

        // Gain experience
        self.gain_experience(10);
    }

    fn gain_experience(&mut self, amount: i32) {
        self.experience += amount;
        let needed = self.level * 100;

        if self.experience >= needed {
            self.level_up();
        }
    }

    fn level_up(&mut self) {
        self.level += 1;
        self.max_health += 20;
        self.health = self.max_health;
        self.attack += 5;
        self.defense += 3;
        self.experience = 0;
        println!("🎉 {} reached level {}!", self.name, self.level);
    }
}

fn main() {
    // ---- Creating a player ----
    let mut hero = Player::new("Aragorn");
    let mut enemy = Player::new("Goblin");

    // ---- Using methods ----
    hero.display();
    enemy.display();

    println!("\n--- Combat ---");
    hero.attack_target(&mut enemy);
    enemy.attack_target(&mut hero);
    hero.attack_target(&mut enemy);

    println!("\n--- Final Stats ---");
    hero.display();
    enemy.display();
}

phase2.brokenCode:
struct Player {
    name: String,
    health: i32,
}

impl Player {
    fn new(name: &str) -> Player {
        Player {
            name: String::from(name),
            health: 100,
        }
    }

    // Forgot &mut self for modifying method
    fn take_damage(self, damage: i32) {
        self.health -= damage;  // ERROR! Can't modify self
    }
}

phase2.explanation:
You need `&mut self` to modify the struct.

**The fix:**
```rust
fn take_damage(&mut self, damage: i32) {
    self.health -= damage;
}
```

**Rust-chan says:**
"If you want to modify, use `&mut self`. If you want to consume, use `self`. The compiler tells you which one to use."
